//
// D2 AU DERIVED COPY of rtl/d2_diag_band.sv (generated by make_d2_derived.py): module d2_diag_band_au = the band with 14
// more cells to the right (16-29); cells 0-15 are unchanged in position, colour and meaning:
//   16 sound-ROM (slot 4) read-back sums (blue until read back, then green = expected sums, red = different)
//   17 PSRAM wave-RAM clear done (green) / not done (red)
//   18 wave-READ watchdog: green = never tripped, red = sdr_p4_req was high > WD_LIMIT clk_sys (sticky)
//   19 wave-WRITE watchdog: the same for sdr_wave_wr_req
//   GA2Audio2 (d2_wave_psram observation; white = 1, grey = 0 unless stated):
//   20 d2_wave_psram rst low (green) / high (red)      21 tPU wait over (green) / running (red)
//   22 clr_idx[15] (all clear writes issued)           23-26 clr_idx[14:11]
//   27 toggles at the end of every PSRAM access        28 sequencer busy
//   29 clear-wait timeout taken (red) / not taken (green): the CPU reset stopped waiting for cell 17
//
// d2_diag_band: a tiny on-screen status band over the APF video stream (clk_vid). D2 Pocket top, exploratory.
// Pattern of pocket_jaguar target/pocket/core_top.sv's diagnostic overlay (proven on the Pocket): position counted on the
// written pixels of the outgoing stream, so the band is also drawn on ga2_video's fallback raster when the core makes
// no video at all.
//
// Placement: DE lines ROW0..ROW0+3 (default 220-223, the bottom four of 224), 16 cells of 8 pixels from x = 8; in each
// cell only pixels 1..6 are drawn, everything else is the game's pixel. Cells, left to right:
//   0 PLL locked          1 SDRAM ready           2 all slots received (dataslot_allcomplete)   3 read-back done
//   4 program-ROM sums    5 tile-ROM sums         (4/5: green = equal to the expected sums, red = different, blue = not
//                                                   yet read back)
//   6 CPU out of reset    7 heartbeat (white/grey; toggles with bit HB_BIT of the work-RAM access counter)
//   8-15 IRQ 64 count, bits 7..0 (white = 1, grey = 0): V2 acknowledges of the per-frame interrupt (vector 0x00)
//   flags 0-3, 6: green = yes, red = no.
// Inputs from other clock domains are display-only, quasi-static or slowly counting: each bit passes a two-flop
// synchronizer (a multi-bit count can show a mixed value for one frame; it is never used for control).
module d2_diag_band_au #(
    parameter int ROW0 = 220,
    parameter int X0   = 8
) (
    input             clk_vid,
    input             en,               // band shown
    // APF stream in (from ga2_video) and out (to the pins)
    input      [23:0] rgb_in,
    input             de, skip, vs,
    output     [23:0] rgb_out,
    output            in_band,          // observation: this pixel is a drawn band pixel
    // status (any domain)
    input             pll_locked, sdram_ready, all_complete, verify_done, sums0_ok, sums1_ok, cpu_running, heartbeat,
    input       [7:0] irq64,
    // AU: cells 16-29 (cells 0-15 keep their meaning)
    input             snd_sums_ok, psram_clear_done, wave_wd_rd, wave_wd_wr,
    input             wv_rst_low, wv_tpu_ok, wv_busy, wv_acc_tgl, wclr_timeout,   // AU2: cells 20, 21, 28, 27, 29
    input      [15:11] wv_clr_idx                                                  // AU2: cells 22-26 (bit 15 first)
);
reg [29:0] s1 = 30'd0, s2 = 30'd0;
always @(posedge clk_vid) begin
    s1 <= {wclr_timeout, wv_busy, wv_acc_tgl, wv_clr_idx[11], wv_clr_idx[12], wv_clr_idx[13], wv_clr_idx[14], wv_clr_idx[15],
           wv_tpu_ok, wv_rst_low,
           wave_wd_wr, wave_wd_rd, psram_clear_done, snd_sums_ok,
           irq64, heartbeat, cpu_running, sums1_ok, sums0_ok, verify_done, all_complete, sdram_ready, pll_locked};
    s2 <= s1;
end
wire [7:0] cnt = s2[15:8];
reg  [9:0] dx = 10'd0;
reg  [8:0] dy = 9'd0;
reg        dde = 1'b0;
always @(posedge clk_vid) begin
    dde <= de;
    if (vs) dy <= 9'd0;
    else if (dde && !de) dy <= dy + 1'b1;
    if (!de) dx <= 10'd0;
    else if (!skip) dx <= dx + 1'b1;
end
localparam [23:0] GRN = 24'h00C000, RED = 24'hE00000, BLU = 24'h0000C0, WHT = 24'hFFFFFF, GRY = 24'h404040;
wire [9:0] rx    = dx - 10'(X0);
wire [4:0] cix  = rx[7:3];   // AU: 30 cells
wire       box   = en && de && !skip && (dy >= 9'(ROW0)) && (dy < 9'(ROW0 + 4)) && (dx >= 10'(X0)) && (dx < 10'(X0 + 240))
                   && (rx[2:0] >= 3'd1) && (rx[2:0] <= 3'd6);
function automatic [23:0] flag(input b); flag = b ? GRN : RED; endfunction
reg [23:0] col;
always @(*) begin
    case (cix)
    5'd0: col = flag(s2[0]);
    5'd1: col = flag(s2[1]);
    5'd2: col = flag(s2[2]);
    5'd3: col = flag(s2[3]);
    5'd4: col = !s2[3] ? BLU : flag(s2[4]);
    5'd5: col = !s2[3] ? BLU : flag(s2[5]);
    5'd6: col = flag(s2[6]);
    5'd7: col = s2[7] ? WHT : GRY;
    5'd16: col = !s2[3] ? BLU : flag(s2[16]);   // AU: sound-ROM (slot 4) sums
    5'd17: col = flag(s2[17]);                  // AU: PSRAM wave-RAM clear done
    5'd18: col = s2[18] ? RED : GRN;            // AU: wave-read watchdog (red = sticky trip)
    5'd19: col = s2[19] ? RED : GRN;            // AU: wave-write watchdog (red = sticky trip)
    5'd20: col = flag(s2[20]);                  // AU2: d2_wave_psram rst low (PLL lock seen in clk_sys)
    5'd21: col = flag(s2[21]);                  // AU2: d2_wave_psram tPU wait over
    5'd22, 5'd23, 5'd24, 5'd25, 5'd26, 5'd27, 5'd28: col = s2[cix] ? WHT : GRY;   // AU2: clr_idx[15:11], access toggle, busy
    5'd29: col = s2[29] ? RED : GRN;            // AU2: clear-wait timeout taken (red)
    default: col = cnt[3'(5'd15 - cix)] ? WHT : GRY;
    endcase
end
assign in_band = box;
assign rgb_out = box ? col : rgb_in;
endmodule
